import{_ as t,o as s,c as a,a3 as n}from"./chunks/framework.B5WAEDB7.js";const u=JSON.parse('{"title":"Router and Parallel","description":"Branch, repeat, and delay the flow of execution within a Flow.","frontmatter":{"title":"Router and Parallel","description":"Branch, repeat, and delay the flow of execution within a Flow."},"headers":[],"relativePath":"en/flows/router-und-parallel.md","filePath":"en/flows/router-und-parallel.md","lastUpdated":1787319236000}'),o={name:"en/flows/router-und-parallel.md"};function i(r,e,l,d,p,h){return s(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="router-parallel-and-wait" tabindex="-1">Router, Parallel, and Wait <a class="header-anchor" href="#router-parallel-and-wait" aria-label="Permalink to &quot;Router, Parallel, and Wait&quot;">​</a></h1><p>The four <strong>helpers</strong> control how a Flow runs, rather than doing something themselves. They live in the editor under the <strong>Helpers</strong> tab.</p><table tabindex="0"><thead><tr><th>Helper</th><th>Description in the interface</th></tr></thead><tbody><tr><td><strong>Router</strong></td><td><em>Take different paths</em></td></tr><tr><td><strong>Parallel</strong></td><td><em>Runs the following steps individually for each list element.</em></td></tr><tr><td><strong>Merge runs</strong></td><td><em>Waits for all list runs and then continues the Flow.</em></td></tr><tr><td><strong>Wait</strong></td><td><em>Pauses the Flow for a set duration.</em></td></tr></tbody></table><hr><h2 id="router" tabindex="-1">Router <a class="header-anchor" href="#router" aria-label="Permalink to &quot;Router&quot;">​</a></h2><p>The Router branches the Flow: depending on a condition, execution continues down a different path.</p><p><strong>Typical uses:</strong></p><ul><li>By amount: over €1000 goes for approval, under that gets confirmed directly</li><li>By category: request goes to the responsible team</li><li>By status: different notifications</li></ul><h3 id="conditions" tabindex="-1">Conditions <a class="header-anchor" href="#conditions" aria-label="Permalink to &quot;Conditions&quot;">​</a></h3><p>You set a condition on each outgoing path. Available operators:</p><table tabindex="0"><thead><tr><th>Operator</th><th></th></tr></thead><tbody><tr><td><em>is equal to</em></td><td><em>is not equal to</em></td></tr><tr><td><em>is greater than</em></td><td><em>is less than</em></td></tr><tr><td><em>is greater than or equal to</em></td><td><em>is less than or equal to</em></td></tr><tr><td><em>starts with</em></td><td><em>ends with</em></td></tr><tr><td><em>contains</em></td><td></td></tr><tr><td><em>is before</em></td><td><em>is after</em></td></tr><tr><td><em>is empty</em></td><td><em>is not empty</em></td></tr><tr><td><em>is true</em></td><td><em>is false</em></td></tr></tbody></table><p>You combine multiple conditions with <strong>and</strong> or <strong>or</strong> — in the dialog via the choice <em>All conditions met (AND)</em> or <em>At least one condition (OR)</em>. It applies to all rows together.</p><p>You pull the values from previous steps — see <a href="/en/flows/daten-zwischen-schritten">Data between steps</a>.</p><div class="tip custom-block"><p class="custom-block-title">The value first, then the condition</p><p>Which operators are offered depends on the type of the chosen value. The dialog knows this type from the last test run — without a test run, all operators appear, including ones that don&#39;t fit. → <a href="/en/flows/testen">Testing Flows</a></p></div><p>For cases that can&#39;t be expressed as rows, the dialog offers <strong>Advanced logic</strong>: there the condition is written as an expression. → <a href="/en/apptivescript/bedingungen#flow-transitions">Building conditions</a></p><div class="tip custom-block"><p class="custom-block-title">Always provide a default path</p><p>If no condition matches, the Flow reaches a dead end at this point. With numbers and select fields, it&#39;s easy to only think of the expected cases and forget empty values.</p><p>Provide a path with <em>is empty</em>, or word the last condition so that it catches everything else.</p></div><div class="warning custom-block"><p class="custom-block-title">Check conditions before going live</p><p>A Router with an incorrectly set condition silently sends cases down the wrong branch — there&#39;s no error message. Test each branch individually with matching test data. → <a href="/en/flows/testen">Testing Flows</a></p></div><hr><h2 id="parallel" tabindex="-1">Parallel <a class="header-anchor" href="#parallel" aria-label="Permalink to &quot;Parallel&quot;">​</a></h2><p><strong>Parallel</strong> is the loop: the step takes a <strong>list</strong> and runs the following steps <strong>individually for each element</strong>.</p><p>There&#39;s almost always a step before it that delivers a list:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Trigger</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Load all entries          →  delivers a list</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Parallel                  →  once per element</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Email                      →  runs per entry</span></span></code></pre></div><p><strong>Typical uses:</strong></p><ul><li>Mail merge to all entries of a view</li><li>Create a job for each line item of an invoice</li><li>Process the rows of an imported CSV file individually</li></ul><div class="tip custom-block"><p class="custom-block-title">Without Parallel, it only happens once</p><p>The most common mistake when working with lists: using <em>Load all entries</em> and then being surprised that the following email only gets sent once — or with unusable content.</p><p>A list isn&#39;t a repetition yet. Only <strong>Parallel</strong> turns it into individual runs.</p></div><div class="warning custom-block"><p class="custom-block-title">Watch out with large lists</p><p>If <em>Parallel</em> runs over an unfiltered view with thousands of entries, the following steps get executed thousands of times — including emails and calls to outside systems.</p><p>Filter the view down to what actually needs processing first, and test with a small set.</p></div><hr><h2 id="merge-runs" tabindex="-1">Merge runs <a class="header-anchor" href="#merge-runs" aria-label="Permalink to &quot;Merge runs&quot;">​</a></h2><blockquote><p><em>Waits for all list runs and then continues the Flow.</em></p></blockquote><p><strong>Parallel</strong> opens a section where the following steps run individually per list element. <strong>Merge runs</strong> closes that section again: the Flow waits until <strong>all</strong> runs are finished, then continues once, a single time.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Load all entries              →  list</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Parallel                      →  from here, per element</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Email                          →  runs per entry</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Merge runs                     →  waits for all</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Update entry                   →  runs only once again</span></span></code></pre></div><p>The step has <strong>no settings</strong> — it only marks the end of the parallel section.</p><div class="tip custom-block"><p class="custom-block-title">What you need it for</p><p>Without this step, everything after <em>Parallel</em> stays in repeat mode. As soon as you want to do something <strong>once</strong> after the loop, you need it:</p><ul><li>send a summary once all the individual emails are out</li><li>set an aggregate status once all line items have been processed</li><li>close out a job once every row of an import has gone through</li></ul></div><div class="tip custom-block"><p class="custom-block-title">Nesting is possible</p><p>Every <em>Parallel</em> opens a level, every <em>Merge runs</em> closes one. This lets you nest loops inside each other — for example per invoice, over its line items.</p><p>Make sure the pairs match up. A missing merge leaves the Flow stuck in repeat mode; an extra one has nothing to close.</p></div><hr><h2 id="wait" tabindex="-1">Wait <a class="header-anchor" href="#wait" aria-label="Permalink to &quot;Wait&quot;">​</a></h2><p><strong>Wait</strong> pauses the Flow for a set duration and then continues it.</p><p><strong>Typical uses:</strong></p><ul><li>Reminder a few days after a sign-up</li><li>Follow-up when no response arrives within a deadline</li><li>Spacing between two calls to an outside system</li></ul><div class="tip custom-block"><p class="custom-block-title">Wait is not scheduling</p><p><em>Wait</em> measures from the moment the step is reached — not up to a fixed date. &quot;Three days after the trigger&quot; works well with it; &quot;every Monday at 9am&quot; does not.</p></div><p>A waiting run has the status <strong>Waiting</strong> in the <a href="/en/flows/durchlaufhistorie">run history</a>.</p><hr><h2 id="merging-list-yes-router-no" tabindex="-1">Merging: list yes, router no <a class="header-anchor" href="#merging-list-yes-router-no" aria-label="Permalink to &quot;Merging: list yes, router no&quot;">​</a></h2><p>The two kinds of branching behave differently:</p><table tabindex="0"><thead><tr><th></th><th>Gets merged back together</th></tr></thead><tbody><tr><td><strong>Parallel</strong> — repetition over a list</td><td><strong>yes</strong>, via <em>Merge runs</em></td></tr><tr><td><strong>Router</strong> — branching by conditions</td><td><strong>no</strong></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Router branches run separately to the end</p><p>There&#39;s no merge step for the Router. Design your flows so that each branch ends on its own.</p><p>If you need the same thing at the end of several branches, add the step in each branch. <em>Merge runs</em> doesn&#39;t help here — it closes a <strong>Parallel</strong> section, not a Router branch.</p></div><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/flows/aktionen">Actions</a></li><li><a href="/en/flows/daten-zwischen-schritten">Data between steps</a></li><li><a href="/en/flows/testen">Testing Flows</a></li></ul>`,48)])])}const m=t(o,[["render",i]]);export{u as __pageData,m as default};
